.stage { position: absolute; inset: 0; overflow: hidden; background: #0b0f14; color: #f4f6f8; font-family: inter, sans-serif; }
.scene { position: absolute; inset: 0; }
.big { position: absolute; margin: 0; font-size: 180px; font-weight: 700; line-height: 1; white-space: nowrap; }
.one { left: 300px; top: 330px; }
.two { left: 380px; top: 420px; color: #5eead4; }
.tiny { position: absolute; margin: 0; left: 40px; top: 700px; font-size: 44px; color: #8a94a3; white-space: nowrap; }
.calm { position: absolute; margin: 0; left: 160px; top: 300px; font-size: 140px; font-weight: 700; white-space: nowrap; }
.low { position: absolute; margin: 0; left: 160px; top: 1000px; font-size: 44px; color: #8a94a3; white-space: nowrap; }
.one, .two, .tiny { animation: a 3.6s ease 0.2s both; }
.calm, .low { animation: a 3.6s ease 4.2s both; }
@keyframes a { 0% { opacity: 0; } 15% { opacity: 1; } 88% { opacity: 1; } 100% { opacity: 0; } }
